table|requests|requests|CREATE TABLE "requests" ( id TEXT PRIMARY KEY, run_id TEXT NOT NULL, workspace_id TEXT NOT NULL, job_id TEXT NOT NULL, kind TEXT NOT NULL, session_id TEXT NOT NULL DEFAULT '', harness TEXT NOT NULL DEFAULT '', runtime TEXT NOT NULL DEFAULT '', working_dir TEXT NOT NULL DEFAULT '', conversation_key TEXT NOT NULL DEFAULT '', conversation_id TEXT NOT NULL DEFAULT '', title TEXT NOT NULL, summary TEXT NOT NULL DEFAULT '', turn INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'pending', answered_by TEXT, answered_via TEXT, answered_at TEXT, expires_at TEXT, delivery_state TEXT NOT NULL DEFAULT 'none', claimed_at TEXT, delivery_path TEXT NOT NULL DEFAULT '', delivered_run_id TEXT, delivered_turn INTEGER, delivery_error TEXT NOT NULL DEFAULT '', source TEXT NOT NULL DEFAULT '', hop_id TEXT NOT NULL DEFAULT '', trace_id TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1 )
table|route_choices|route_choices|CREATE TABLE route_choices ( workspace_id TEXT NOT NULL, connection TEXT NOT NULL, conversation_key TEXT NOT NULL, status TEXT NOT NULL, route_id TEXT, target TEXT, method TEXT NOT NULL, rule_index INTEGER, decision_id TEXT, pick_route_id TEXT, first_event_id TEXT NOT NULL, inbox_id TEXT, attempts INTEGER NOT NULL DEFAULT 0, revision INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY (workspace_id, connection, conversation_key) )
table|run_events|run_events|CREATE TABLE run_events ( id INTEGER PRIMARY KEY AUTOINCREMENT, -- Postgres-port: GENERATED ALWAYS AS IDENTITY run_id TEXT NOT NULL, at TEXT NOT NULL, kind TEXT NOT NULL, source TEXT, detail_json TEXT, trace_id TEXT )
table|run_segments|run_segments|CREATE TABLE run_segments ( id INTEGER PRIMARY KEY AUTOINCREMENT, -- Postgres-port: GENERATED ALWAYS AS IDENTITY run_id TEXT NOT NULL, layer TEXT NOT NULL, state TEXT NOT NULL, started_at TEXT NOT NULL, ended_at TEXT, duration_ms INTEGER, reason TEXT, source TEXT, detail_json TEXT )
table|run_turns|run_turns|CREATE TABLE run_turns ( run_id TEXT NOT NULL, n INTEGER NOT NULL, reason TEXT NOT NULL, status TEXT NOT NULL, end_reason TEXT, queue_id TEXT, trigger_event_id TEXT, prompt_preview TEXT NOT NULL DEFAULT '', session_id TEXT, started_at TEXT NOT NULL, ended_at TEXT, duration_ms INTEGER, tokens_input INTEGER, tokens_output INTEGER, tokens_cache_read INTEGER, tokens_cache_creation INTEGER, tokens_model TEXT, trace_id TEXT NOT NULL DEFAULT '', hop_id TEXT NOT NULL DEFAULT '', depth INTEGER NOT NULL DEFAULT 0, path_json TEXT NOT NULL DEFAULT '[]', tokens_cost_usd REAL, PRIMARY KEY (run_id, n) )
table|runs|runs|CREATE TABLE "runs" ( id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, job_id TEXT NOT NULL, kind TEXT NOT NULL DEFAULT 'job', reason TEXT, status TEXT NOT NULL, end_reason TEXT, prompt_preview TEXT, inputs_json TEXT, trigger_event_id TEXT, trigger_connector TEXT, trigger_capture_json TEXT, trigger_vars_json TEXT, conversation_key TEXT, conversation_id TEXT, session_id TEXT, runtime TEXT NOT NULL DEFAULT 'tui', harness TEXT, pane_session TEXT, tokens_input INTEGER, tokens_output INTEGER, tokens_cache_read INTEGER, tokens_cache_creation INTEGER, tokens_model TEXT, started_at TEXT NOT NULL, ended_at TEXT, max_duration_ms INTEGER NOT NULL DEFAULT 0, idle_timeout_ms INTEGER NOT NULL DEFAULT 0, keep_alive_ms INTEGER NOT NULL DEFAULT 0, nudge_ms INTEGER NOT NULL DEFAULT -1, resumable_ms INTEGER NOT NULL DEFAULT 0, previous_run_id TEXT, resume_attempts INTEGER NOT NULL DEFAULT 0, queue_id TEXT, claimed_by TEXT, trace_id TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1, updated_at TEXT NOT NULL, working_dir TEXT, memory_hash TEXT NOT NULL DEFAULT '', outcome TEXT, outcome_note TEXT NOT NULL DEFAULT '', outcome_at TEXT, runtime_pid INTEGER, attach_kind TEXT, actor_token_hash TEXT NOT NULL DEFAULT '', connectors_json TEXT, turn_count INTEGER NOT NULL DEFAULT 1, turn_started_at TEXT, active_ms INTEGER NOT NULL DEFAULT 0 , harness_version TEXT, trigger_batch_json TEXT, folder_env TEXT, trigger_source TEXT, visor_session_id TEXT, visor_seq INTEGER NOT NULL DEFAULT 0, pruned_at TEXT, tokens_cost_usd REAL, trigger_route_id TEXT NOT NULL DEFAULT '')
table|schedules|schedules|CREATE TABLE "schedules" ( workspace_id TEXT NOT NULL, job_id TEXT NOT NULL, idx INTEGER NOT NULL DEFAULT 0, spec TEXT NOT NULL, timezone TEXT NOT NULL DEFAULT 'UTC', catch_up INTEGER NOT NULL DEFAULT 1, next_due_at TEXT, last_fired_at TEXT, anchor TEXT, updated_at TEXT NOT NULL, artifact_id TEXT NOT NULL DEFAULT '', PRIMARY KEY (workspace_id, job_id, idx) )
table|schema_migrations|schema_migrations|CREATE TABLE schema_migrations ( version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL )
table|skill_index|skill_index|CREATE TABLE "skill_index" ( ref TEXT PRIMARY KEY, name TEXT NOT NULL, scope TEXT NOT NULL DEFAULT 'global', owner_id TEXT NOT NULL DEFAULT '', workspace_id TEXT NOT NULL DEFAULT '', provenance TEXT NOT NULL, path TEXT NOT NULL, hash TEXT, used_30d INTEGER NOT NULL DEFAULT 0, updated_at TEXT NOT NULL, source_kind TEXT, source_ref TEXT, created_by_kind TEXT, created_by_job TEXT, created_by_run TEXT, status TEXT NOT NULL DEFAULT 'active', note TEXT , archived_at TEXT)
table|state_fts|state_fts|CREATE VIRTUAL TABLE state_fts USING fts5( key, body, content='', tokenize='unicode61 remove_diacritics 2' )
table|state_rows|state_rows|CREATE TABLE state_rows ( owner_id TEXT NOT NULL, collection TEXT NOT NULL, key TEXT NOT NULL, value TEXT NOT NULL, at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, expires_at TEXT, run_id TEXT, UNIQUE (owner_id, collection, key) )
table|state_run_stats|state_run_stats|CREATE TABLE state_run_stats ( owner_id TEXT NOT NULL, run_id TEXT NOT NULL, collection TEXT NOT NULL, inserted INTEGER NOT NULL DEFAULT 0, updated INTEGER NOT NULL DEFAULT 0, deleted INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (owner_id, run_id, collection) )
table|system_flags|system_flags|CREATE TABLE system_flags ( key TEXT PRIMARY KEY, value TEXT NOT NULL )
table|uploads|uploads|CREATE TABLE uploads ( id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, mime TEXT NOT NULL, size INTEGER NOT NULL, sha256 TEXT NOT NULL, created_at TEXT NOT NULL, attached_at TEXT )
table|webhook_deliveries|webhook_deliveries|CREATE TABLE webhook_deliveries ( id TEXT PRIMARY KEY, connection_id TEXT NOT NULL, request_json TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, next_attempt_at TEXT NOT NULL, last_error TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL )
table|workspace_moves|workspace_moves|CREATE TABLE workspace_moves ( id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, machine_id TEXT NOT NULL, phase TEXT NOT NULL, error TEXT NOT NULL DEFAULT '', restored INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL )
table|workspaces|workspaces|CREATE TABLE workspaces ( id TEXT PRIMARY KEY, name TEXT NOT NULL, path TEXT NOT NULL, git_enabled INTEGER NOT NULL DEFAULT 0, orphaned INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL , revision INTEGER NOT NULL DEFAULT 1, handle TEXT NOT NULL DEFAULT '', machine_id TEXT, archived_at TEXT, moved_to TEXT, move_id TEXT)
